From 7e44c05687f8e68faa01a4dc8e8e1b269b5fa8cb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 20:30:38 +0100
Subject: [PATCH] klipper: Add a filter to show only text, images or files in
 the history

The clipboard history could only be narrowed down by text or starred
state, so finding an image or a copied file meant scrolling through all
of it. Add a filter button next to the search field to show one type.

BUG: 485127
---
 .../declarative/declarativehistorymodel.cpp   | 28 ++++++-
 klipper/declarative/declarativehistorymodel.h |  6 ++
 klipper/declarative/qml/ClipboardMenu.qml     | 75 ++++++++++++++++++-
 3 files changed, 104 insertions(+), 5 deletions(-)

diff --git a/klipper/declarative/declarativehistorymodel.cpp b/klipper/declarative/declarativehistorymodel.cpp
index 9c44a5188b..1873a821ce 100644
--- a/klipper/declarative/declarativehistorymodel.cpp
+++ b/klipper/declarative/declarativehistorymodel.cpp
@@ -23,6 +23,11 @@ DeclarativeHistoryModel::DeclarativeHistoryModel(QObject *parent)
     connect(m_model.get(), &HistoryModel::rowsInserted, this, &DeclarativeHistoryModel::sourceCountChanged);
     connect(m_model.get(), &HistoryModel::rowsRemoved, this, &DeclarativeHistoryModel::sourceCountChanged);
     connect(m_model.get(), &HistoryModel::modelReset, this, &DeclarativeHistoryModel::sourceCountChanged);
+    connect(this, &DeclarativeHistoryModel::sourceCountChanged, this, [this] {
+        if (m_model->rowCount() == 0) {
+            setTypeFilter(0);
+        }
+    });

     m_starredCountNotifier = m_model->bindableStarredCount().addNotifier([this] {
         if (m_starredOnly && m_model->bindableStarredCount().value() == 0) {
@@ -67,6 +72,21 @@ void DeclarativeHistoryModel::setStarredOnly(bool value)
     Q_EMIT starredOnlyChanged();
 }

+int DeclarativeHistoryModel::typeFilter() const
+{
+    return m_typeFilter;
+}
+
+void DeclarativeHistoryModel::setTypeFilter(int type)
+{
+    if (m_typeFilter == type) {
+        return;
+    }
+    m_typeFilter = type;
+    invalidateRowsFilter();
+    Q_EMIT typeFilterChanged();
+}
+
 void DeclarativeHistoryModel::moveToTop(const QString &uuid)
 {
     m_model->moveToTop(uuid);
@@ -100,8 +120,12 @@ void DeclarativeHistoryModel::invokeAction(const QString &uuid)

 bool DeclarativeHistoryModel::filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const
 {
-    if (m_starredOnly) {
-        return m_model->index(sourceRow, 0, sourceParent).data(HistoryModel::StarredRole).toBool();
+    const QModelIndex index = m_model->index(sourceRow, 0, sourceParent);
+    if (m_starredOnly && !index.data(HistoryModel::StarredRole).toBool()) {
+        return false;
+    }
+    if (m_typeFilter != 0 && index.data(HistoryModel::TypeIntRole).toInt() != m_typeFilter) {
+        return false;
     }

     return true;
diff --git a/klipper/declarative/declarativehistorymodel.h b/klipper/declarative/declarativehistorymodel.h
index bd239fbbc8..25881cdaf7 100644
--- a/klipper/declarative/declarativehistorymodel.h
+++ b/klipper/declarative/declarativehistorymodel.h
@@ -26,6 +26,7 @@ class DeclarativeHistoryModel : public QSortFilterProxyModel
     Q_PROPERTY(QString currentText READ currentText NOTIFY currentTextChanged)

     Q_PROPERTY(bool starredOnly READ starredOnly WRITE setStarredOnly NOTIFY starredOnlyChanged)
+    Q_PROPERTY(int typeFilter READ typeFilter WRITE setTypeFilter NOTIFY typeFilterChanged)

 public:
     explicit DeclarativeHistoryModel(QObject *parent = nullptr);
@@ -38,6 +39,9 @@ public:
     bool starredOnly() const;
     void setStarredOnly(bool value);

+    int typeFilter() const;
+    void setTypeFilter(int type);
+
     Q_INVOKABLE void moveToTop(const QString &uuid);
     Q_INVOKABLE void setText(const QString &uuid, const QString &text);

@@ -52,6 +56,7 @@ Q_SIGNALS:
     void starredCountChanged();
     void currentTextChanged();
     void starredOnlyChanged();
+    void typeFilterChanged();

 protected:
     bool filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const override;
@@ -59,5 +64,6 @@ protected:
 private:
     std::shared_ptr<HistoryModel> m_model;
     bool m_starredOnly = false;
+    int m_typeFilter = 0;
     QPropertyNotifier m_starredCountNotifier;
 };
diff --git a/klipper/declarative/qml/ClipboardMenu.qml b/klipper/declarative/qml/ClipboardMenu.qml
index b067c9c8af..c83f278b9f 100644
--- a/klipper/declarative/qml/ClipboardMenu.qml
+++ b/klipper/declarative/qml/ClipboardMenu.qml
@@ -248,6 +248,13 @@ PlasmaComponents3.ScrollView {
         icon.name: "starred-symbolic"
     }

+    component TypeFilterMenuItem: PlasmaComponents3.MenuItem {
+        required property int type
+        checkable: true
+        autoExclusive: true
+        onClicked: clipboardMenu.model.typeFilter = type
+    }
+
     // Exported metrics for delegates
     readonly property int starMetricsImplicitWidth: metricsStarButton.implicitWidth
     readonly property int starMetricsImplicitHeight: metricsStarButton.implicitHeight
@@ -265,7 +272,7 @@ PlasmaComponents3.ScrollView {
                     Layout.fillWidth: true
                     enabled: menuListView.count > 0 || filter.text.length > 0
                     KeyNavigation.up: clipboardMenu.dialogItem.KeyNavigation.up /* ToolBar */
-                    KeyNavigation.right: clearHistoryButton.visible ? clearHistoryButton : (tabBar.visible ? tabBar : null)
+                    KeyNavigation.right: typeFilterButton
                     Keys.onDownPressed: event => {
                         if (tabBar.visible) {
                             tabBar.forceActiveFocus(Qt.TabFocusReason);
@@ -287,6 +294,68 @@ PlasmaComponents3.ScrollView {
                     }
                 }

+                PlasmaComponents3.ToolButton {
+                    id: typeFilterButton
+                    enabled: clipboardMenu.model.sourceCount > 0
+
+                    icon.name: "view-filter"
+
+                    display: PlasmaComponents3.AbstractButton.IconOnly
+                    text: i18nd("klipper", "Show Only…")
+                    checked: clipboardMenu.model.typeFilter !== 0
+                    down: typeFilterMenu.opened || pressed
+                    Accessible.role: Accessible.ButtonMenu
+
+                    KeyNavigation.left: filter
+                    KeyNavigation.right: clearHistoryButton.visible ? clearHistoryButton : (tabBar.visible ? tabBar : null)
+                    KeyNavigation.down: tabBar.visible ? tabBar : menuListView
+
+                    onClicked: {
+                        if (typeFilterMenu.visible) {
+                            typeFilterMenu.dismiss();
+                        } else {
+                            typeFilterMenu.open();
+                        }
+                    }
+
+                    PlasmaComponents3.ToolTip {
+                        text: typeFilterButton.text
+                    }
+
+                    PlasmaComponents3.Menu {
+                        id: typeFilterMenu
+                        y: typeFilterButton.height
+
+                        onAboutToShow: {
+                            for (let i = 0; i < count; ++i) {
+                                const item = itemAt(i) as TypeFilterMenuItem;
+                                item.checked = item.type === clipboardMenu.model.typeFilter;
+                            }
+                        }
+
+                        // Values from HistoryItemType in historyitem.h
+                        TypeFilterMenuItem {
+                            type: 0
+                            text: i18nd("klipper", "All Types")
+                        }
+                        TypeFilterMenuItem {
+                            type: 2
+                            text: i18nd("klipper", "Text")
+                            icon.name: "text-plain"
+                        }
+                        TypeFilterMenuItem {
+                            type: 4
+                            text: i18nd("klipper", "Images")
+                            icon.name: "image-x-generic"
+                        }
+                        TypeFilterMenuItem {
+                            type: 8
+                            text: i18nd("klipper", "Files")
+                            icon.name: "document-open"
+                        }
+                    }
+                }
+
                 PlasmaComponents3.ToolButton {
                     id: clearHistoryButton
                     visible: clipboardMenu.showsClearHistoryButton
@@ -296,7 +365,7 @@ PlasmaComponents3.ScrollView {
                     display: PlasmaComponents3.AbstractButton.IconOnly
                     text: i18nd("klipper", "Clear History")

-                    KeyNavigation.left: filter
+                    KeyNavigation.left: typeFilterButton
                     KeyNavigation.down: tabBar.visible ? tabBar : menuListView

                     onClicked: clipboardMenu.clearHistory()
@@ -527,7 +596,7 @@ PlasmaComponents3.ScrollView {

             sourceComponent: PlasmaExtras.PlaceholderMessage {
                 width: parent.width
-                readonly property bool hasText: filter.text.length > 0
+                readonly property bool hasText: filter.text.length > 0 || clipboardMenu.model.typeFilter !== 0
                 iconName: hasText ? "edit-none" : "edit-paste"
                 text: hasText ? i18nd("klipper", "No matches") : i18nd("klipper", "Clipboard is empty")
             }
-- 
